const fs = require('fs');
const vm = require('vm');
const path = 'web/flutter_bootstrap.js';
if (!fs.existsSync(path)) {
  console.log('kanban_firefox_single_surface_missing');
  process.exit(1);
}
let source = fs.readFileSync(path, 'utf8');
source = source.replace('{{flutter_js}}', '').replace('{{flutter_build_config}}', '');
function loadFor(userAgent) {
  let received = null;
  const context = {
    navigator: { userAgent },
    _flutter: { loader: { load: (args) => { received = args; } } },
  };
  vm.createContext(context);
  vm.runInContext(source, context);
  return received;
}
const firefox = loadFor('Mozilla/5.0 Firefox/155.0');
const chromium = loadFor('Mozilla/5.0 Chrome/140.0.0.0 Safari/537.36');
const firefoxConfig = firefox && firefox.config;
const chromiumConfig = chromium && chromium.config;
const ok =
  firefoxConfig &&
  firefoxConfig.canvasKitMaximumSurfaces === 1 &&
  !Object.prototype.hasOwnProperty.call(firefoxConfig, 'canvasKitForceCpuOnly') &&
  chromiumConfig &&
  Object.keys(chromiumConfig).length === 0 &&
  (source.match(/_flutter\.loader\.load\(/g) || []).length === 1;
console.log(ok ? 'kanban_firefox_single_surface_ok' : 'kanban_firefox_single_surface_missing');
process.exit(ok ? 0 : 1);

